from __future__ import annotations

import json
from pathlib import Path
from typing import Any

PAGE_TEMPLATE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Factorio Crafting Mall Planner</title>
<style>
:root{color-scheme:light;--paper:#f4f3ed;--surface:#fff;--ink:#202a28;--muted:#66716c;--line:#d6dbd3;--green:#276b52;--green-soft:#e4f1e9;--orange:#a65122;--orange-soft:#f9eadf}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#ebece5,#f7f5ef 45%,#e8eee8);color:var(--ink);font:16px/1.45 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:28px 20px 56px}header{display:flex;justify-content:space-between;align-items:end;gap:20px;border-bottom:1px solid var(--line);padding-bottom:18px}h1{font-size:2rem;margin:0}header p{margin:4px 0 0;color:var(--muted)}.counts{display:flex;gap:18px;color:var(--muted);white-space:nowrap}.counts strong{color:var(--ink);font-size:1.2rem}.toolbar{display:grid;grid-template-columns:minmax(220px,1fr) auto;gap:14px;align-items:end;margin:22px 0}label{display:block;font-weight:650;margin-bottom:6px}input{font:inherit;width:100%;padding:10px 12px;border:1px solid #aeb8af;border-radius:5px;background:#fff}.filters{display:flex;border:1px solid #aeb8af;border-radius:5px;overflow:hidden}.filters button,.choice{font:inherit;cursor:pointer}.filters button{border:0;border-right:1px solid #aeb8af;background:#fff;padding:10px 14px}.filters button:last-child{border:0}.filters button[aria-pressed=true]{background:var(--ink);color:#fff}.items{border-top:1px solid var(--line)}.item{display:grid;grid-template-columns:minmax(200px,1fr) minmax(200px,1.3fr) auto;gap:18px;align-items:center;padding:14px 4px;border-bottom:1px solid var(--line)}.name{font-weight:700}.key{display:block;color:var(--muted);font-size:.84rem;font-weight:400}.recipes{color:var(--muted);font-size:.9rem}.recipe{margin:3px 0}.actions{display:flex;gap:6px;white-space:nowrap}.choice{border:1px solid var(--line);border-radius:4px;background:#fff;padding:7px 10px;color:var(--ink)}.choice[data-state=mall]{border-color:var(--green);background:var(--green-soft);color:#194d39}.choice[data-state=manual]{border-color:var(--orange);background:var(--orange-soft);color:#7d3b16}.empty{padding:28px 4px;color:var(--muted)}@media(max-width:720px){header{display:block}.counts{margin-top:12px}.toolbar{grid-template-columns:1fr}.item{grid-template-columns:1fr;gap:7px}.actions{margin-top:4px}}
</style><style>.tool-link{display:inline-block;margin-top:8px;color:var(--green);font-weight:650;text-underline-offset:3px}</style></head><body><main><header><div><h1>Crafting Mall Planner</h1><p>Sort craftable items into permanent mall production or occasional manual builds.</p><a class="tool-link" href="factorio-technology-costs.html">Open the Technology Cost Planner</a></div><div class="header-tools"><div class="filters mod-switch" role="group" aria-label="Factorio data set"><button type="button" data-mod="base">Base</button><button type="button" data-mod="space-age">Space Age</button></div><div class="counts"><span><strong id="mall-count">0</strong> mall</span><span><strong id="manual-count">0</strong> manual</span></div></div></header>
<div class="toolbar"><div><label for="search">Search items</label><input id="search" type="search" placeholder="Name or internal ID" autocomplete="off"></div><div class="filters item-filters" role="group" aria-label="Show items"><button type="button" data-filter="all" aria-pressed="true">All</button><button type="button" data-filter="unassigned" aria-pressed="false">Unsorted</button><button type="button" data-filter="mall" aria-pressed="false">Mall</button><button type="button" data-filter="manual" aria-pressed="false">Manual</button></div></div><div id="items" class="items" aria-live="polite"></div>
</main><script>
const datasets=__ITEMS__, labelsByDataset=__LABELS__, defaultMod=__DEFAULT_MOD__, storageKey='factorio-crafting-mall-v1';let modSet=defaultMod;
let graph=datasets[modSet]||datasets[defaultMod], itemLabels=labelsByDataset[modSet]||labelsByDataset[defaultMod], assignments={}, filter='all';const container=document.getElementById('items'),search=document.getElementById('search');
function loadAssignments(){try{const key=storageKey+':'+modSet;let saved=localStorage.getItem(key);if(!saved&&modSet==='space-age')saved=localStorage.getItem(storageKey);assignments=JSON.parse(saved||'{}')||{}}catch{assignments={}}}
function setDataset(next){if(!datasets[next])return;modSet=next;graph=datasets[next];itemLabels=labelsByDataset[next];loadAssignments();document.querySelectorAll('.mod-switch button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mod===next)));render()}
function text(value){return itemLabels[value]||value}function save(){try{localStorage.setItem(storageKey+':'+modSet,JSON.stringify(assignments))}catch{}render()}function setState(name,state){if(assignments[name]===state)delete assignments[name];else assignments[name]=state;save()}
function render(){const query=search.value.trim().toLocaleLowerCase();const names=Object.keys(graph).filter(name=>graph[name].recipes.length&&(!query||text(name).toLocaleLowerCase().includes(query)||name.toLocaleLowerCase().includes(query))).filter(name=>filter==='all'||(filter==='unassigned'?!assignments[name]:assignments[name]===filter)).sort((a,b)=>text(a).localeCompare(text(b)));document.getElementById('mall-count').textContent=Object.values(assignments).filter(x=>x==='mall').length;document.getElementById('manual-count').textContent=Object.values(assignments).filter(x=>x==='manual').length;container.replaceChildren();if(!names.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='No matching craftable items.';container.append(empty);return}for(const name of names){const node=graph[name],row=document.createElement('article'),label=document.createElement('div'),detail=document.createElement('div'),actions=document.createElement('div');row.className='item';label.className='name';label.textContent=text(name);const key=document.createElement('span');key.className='key';key.textContent=name;label.append(key);detail.className='recipes';for(const recipe of node.recipes){const line=document.createElement('div');line.className='recipe';line.textContent=recipe.ingredients.length?recipe.ingredients.map(x=>`${text(x.name)} × ${x.amount}`).join(' + '):'No ingredients';detail.append(line)}actions.className='actions';for(const [state,title] of [['mall','Mall'],['manual','Build as needed']]){const button=document.createElement('button');button.type='button';button.className='choice';button.textContent=title;button.dataset.state=assignments[name]===state?state:'';button.setAttribute('aria-pressed',String(assignments[name]===state));button.onclick=()=>setState(name,state);actions.append(button)}row.append(label,detail,actions);container.append(row)}}
document.querySelectorAll('.mod-switch button').forEach(button=>button.addEventListener('click',()=>setDataset(button.dataset.mod)));search.addEventListener('input',render);document.querySelectorAll('.item-filters button').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('.item-filters button').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));render()}));loadAssignments();document.querySelectorAll('.mod-switch button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mod===modSet)));render();
</script></body></html>'''


def write_crafting_page(datasets: dict[str, dict[str, Any]], output: Path, default_mod: str = "base") -> None:
    labels = {mod: {name: item.get("label", name) for name, item in items.items()} for mod, items in datasets.items()}
    payload = json.dumps(datasets, ensure_ascii=False, separators=(",", ":"))
    label_payload = json.dumps(labels, ensure_ascii=False, separators=(",", ":"))
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    label_payload = label_payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    template = PAGE_TEMPLATE.replace(
        "</style>",
        ".header-tools{display:flex;align-items:center;gap:18px}@media(max-width:720px){.header-tools{justify-content:space-between;margin-top:12px}.counts{margin-top:0}}</style>",
        1,
    )
    html = template.replace("__ITEMS__", payload).replace("__LABELS__", label_payload).replace("__DEFAULT_MOD__", json.dumps(default_mod))
    output.write_text(html, encoding="utf-8")
